# Check what memories exist in the harness
from rlm import get_harness_state

state = get_harness_state()
print("All memory entries:")
for key in dir(state):
    if key.startswith('memory_') or key.startswith('task_'):
        print(f"  {key}")

# Check overview
print("\n=== Overview ===")
try:
    print(state.overview())
except Exception as e:
    print(f"Overview error: {e}")
